            margin-bottom: 40px;
        }
        .section {
            margin-bottom: 30px;
            padding: 20px;
            background-color: white;
            border-radius: 8px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.1);
        }
        .proposal-title {
            text-align: center;
            font-size: 2.5em;
            color: #d35400;
        }
